---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Health score: A design system score made of a few checks you can open.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change health-score.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './health-score.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" draws it in the Soft style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft") */
  'data-style'?: 'soft';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', className]} data-c="health-score" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="hsx panel">
  <div class="hsx-top">
    <div class="hsx-g"><svg viewBox="0 0 120 70"><path d="M10 64a50 50 0 0 1 100 0" class="tr"/><path d="M10 64a50 50 0 0 1 100 0" class="fl"/></svg><div class="hsx-v"><b class="num">0</b><span class="muted">of 100</span></div></div>
    <div class="hsx-s"><b>Design system health</b><span class="muted hsx-st">Good, 2 checks need work</span></div>
  </div>
  <div class="hsx-list"></div>
</div>
  </Fragment></div>
</div>
<script>
  import './health-score.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Health score ---------- */
.hsx{padding:var(--dm-s-4);display:flex;flex-direction:column;gap:var(--dm-s-3);--dm-hs-ok:#16b558;--dm-hs-bad:#e5383b}
:root[data-theme="dark"] .hsx{--dm-hs-ok:#34d27a;--dm-hs-bad:#ff5c5f}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .hsx{--dm-hs-ok:#34d27a;--dm-hs-bad:#ff5c5f}}
.hsx-top{display:flex;align-items:center;gap:14px}
.hsx-g{position:relative;width:150px;height:90px;flex:none}
.hsx-g svg{width:100%;height:100%;overflow:visible}
.hsx-g path{fill:none;stroke-width:9;stroke-linecap:round}
.hsx-g .tr{stroke:var(--dm-line)}
.hsx-g .fl{stroke:var(--dm-accent-mark,var(--dm-accent));stroke-dasharray:157;stroke-dashoffset:157;transition:stroke-dashoffset .9s var(--dm-ease),stroke .4s}
.hsx-v{position:absolute;left:0;right:0;bottom:0;display:flex;flex-direction:column;align-items:center;line-height:1.1}
/* the score is the one big number in the card (owner, 3 Nov: bigger and bolder than the 14px / 500 rule) */
.hsx-v b{font-size:32px;font-weight:600;letter-spacing:-.03em;line-height:1}
.hsx-v span{font-size:11px;margin-top:2px}
.hsx-s{display:flex;flex-direction:column;font-size:13.5px}
.hsx-s b{font-weight:500}
.hsx-st{font-size:12.5px}
.hsx-list{display:flex;flex-direction:column;gap:2px;padding-top:var(--dm-s-3);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.hsx-c{border-radius:calc(10px * var(--dm-rk));transition:background .2s}
.hsx-c.open{background:var(--dm-row)}
@media (hover:hover) and (pointer:fine){.hsx-c:hover{background:var(--dm-row)}}
.hsx-ch{display:flex;align-items:center;gap:10px;width:100%;padding:var(--dm-s-2);font-size:13px;text-align:left}
.hsx-ch .t{flex:1}
.hsx-ch .bar{width:70px;height:5px;border-radius:3px;background:var(--dm-line);overflow:hidden}
.hsx-ch .bar i{display:block;height:100%;border-radius:3px;transition:width .8s var(--dm-ease),background .4s}
.hsx-ch .v{width:26px;text-align:right;font-size:12px;color:var(--dm-fg2)}
.hsx-ch>svg{color:var(--dm-muted);transition:transform .35s var(--dm-ease)}
.hsx-c.open .hsx-ch>svg{transform:rotate(90deg)}
.hsx-d{padding:0 var(--dm-s-2) 10px var(--dm-s-2);font-size:12.5px;color:var(--dm-fg2);display:flex;align-items:center;gap:10px;line-height:1.45}
.hsx-d span{flex:1}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, DM, I, swap, tween } from '../core/core.js';
DM.def('health-score', (r, c) => {
  const K = [['Token usage',96,'All colours come from the library'],['Contrast',88,'2 text pairs below AA on the pricing page',1],['Component reuse',74,'11 detached instances in Checkout',1],['Naming',91,'Layer names follow the convention']];
  const list = $('.hsx-list', r), fl = $('.hsx-g .fl', r), vb = $('.hsx-v b', r), st = $('.hsx-st', r);
  let score = 0;
  const col = v => v >= 90 ? 'var(--dm-hs-ok)' : v >= 80 ? 'var(--dm-accent-mark,var(--dm-accent))' : 'var(--dm-hs-bad)';
  const tl = $('.hsx-s b', r);
  // the gauge shows one value at a time: the overall score, or the check under the pointer or the keyboard focus
  let shown = -1, run = 0;
  function gauge(v){ fl.style.strokeDashoffset = 157 * (1 - v / 100); fl.style.stroke = col(v); const id = ++run, from = score; tween(from, v, 700, n => { if (id === run){ score = n; vb.textContent = Math.round(n); } }); }
  function total(){ if (shown >= 0) return; const t = Math.round(K.reduce((a, k) => a + k[1], 0) / K.length); gauge(t); swap(tl, 'Design system health'); const n = K.filter(k => k[1] < 90).length; swap(st, n ? (t >= 85 ? 'Good' : 'Fair') + ', ' + n + (n > 1 ? ' checks need' : ' check needs') + ' work' : 'Excellent, all checks pass'); }
  function show(i){ if (shown === i) return; shown = i; if (i < 0) return total(); gauge(K[i][1]); swap(tl, K[i][0]); swap(st, K[i][2]); }
  list.innerHTML = K.map(k => `<div class="hsx-c"><button class="hsx-ch"><span class="t">${k[0]}</span><span class="bar"><i style="width:0"></i></span><span class="v num">${k[1]}</span>${I('chev-r','xs')}</button><div class="fold shut"><div><div class="hsx-d"><span>${k[2]}</span>${k[3] ? `<button class="pill soft sm">${I('wand','xs')}Fix</button>` : ''}</div></div></div></div>`).join('');
  $$('.hsx-c', list).forEach((el, i) => {
    $('.hsx-ch', el).onclick = () => { const o = !el.classList.contains('open'); el.classList.toggle('open', o); $('.fold', el).classList.toggle('shut', !o); };
    // pointing at a check (or tabbing to it) swings the gauge to its score and names it; leaving the list swings back
    c.on(el, 'pointerenter', e => { if (e.pointerType !== 'touch') show(i); });
    c.on(el, 'focusin', () => show(i));
    const bar = () => { const b = $('.bar i', el); b.style.width = K[i][1] + '%'; b.style.background = col(K[i][1]); };
    c.later(300 + i * 80, bar);
    const fx = $('.hsx-d .pill', el);
    if (fx) fx.onclick = () => c.run(async () => { fx.innerHTML = '<span class="spin"></span>'; await c.wait(900); K[i][1] = i === 1 ? 97 : 93; K[i][3] = 0; K[i][2] = i === 1 ? 'Fixed. Both pairs now pass AA' : 'Fixed. Reattached 11 instances'; bar(); tween(+$('.v', el).textContent, K[i][1], 700, n => $('.v', el).textContent = Math.round(n)); swap($('.hsx-d span', el), K[i][2]); fx.remove(); if (shown === i){ shown = -2; show(i); } else total(); });
  });
  c.on(list, 'pointerleave', () => { if (!list.contains(document.activeElement)) show(-1); });
  c.on(list, 'focusout', e => { if (!list.contains(e.relatedTarget) && !list.matches(':hover')) show(-1); });
  c.later(280, total);
});
